  h2 { color: #2c3e50; }
  .option { display: block; padding: 12px 16px; margin: 10px 0; background: #ecf0f1;
            border: none; border-radius: 8px; width: 100%; text-align: left;
            cursor: pointer; font-size: 15px; transition: background 0.2s; }
